+export function computeReviewDiff(eventContext: EventContext, workingDir: string): string {
+  const range = resolveDiffRange(eventContext, workingDir);
+  if (!range) {
+    return REVIEW_DIFF_EMPTY_PLACEHOLDER;
+  }
